pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint256 oldPot;
        try c.pot() returns (uint256 __r) { oldPot = __r; } catch { return; }
        bool reverted;
        try c.play{value: value}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 newPot;
        try c.pot() returns (uint256 __r) { newPot = __r; } catch { return; }
        assertTrue((!reverted) == (value == 10));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
